//! Somali inflection, learned from Wiktionary.
//!
//! Generated by morphe from the Kaikki Somali dump of 2026-10-03. Do not edit.
//! Every function is total: unknown words are inflected by prediction, and
//! the `_scored` versions give every candidate with a confidence, best first.
//! Variant confidences reflect Wiktionary's listing order, not measured usage.
//!
//! Data: Wiktionary contributors, CC BY-SA 4.0, via kaikki.org.

#![forbid(unsafe_code)]

pub use morphe::{Options, Scored};
use std::sync::OnceLock;

static DATA: &[u8] = include_bytes!("model.bin");

/// The trained model, for dynamic queries.
pub fn model() -> Option<&'static morphe::Model> {
    static MODEL: OnceLock<Option<morphe::Model>> = OnceLock::new();
    MODEL.get_or_init(|| morphe::Model::decode(DATA)).as_ref()
}

fn best(scored: Scored<String>, word: &str) -> String {
    scored.into_iter().next().map_or_else(|| word.split(',').next().unwrap_or(word).trim().to_string(), |x| x.0)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Gender {
    Masculine,
    Feminine,
}

impl Gender {
    pub const ALL: [Self; 2] = [Self::Masculine, Self::Feminine];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Number {
    Singular,
    Plural,
}

impl Number {
    pub const ALL: [Self; 2] = [Self::Singular, Self::Plural];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Case {
    Absolutive,
    Nominative,
    Genitive,
    Vocative,
}

impl Case {
    pub const ALL: [Self; 4] = [Self::Absolutive, Self::Nominative, Self::Genitive, Self::Vocative];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Possessor {
    FirstSingular,
    SecondSingular,
    ThirdMasculine,
    ThirdFeminine,
    FirstPluralExclusive,
    FirstPluralInclusive,
    SecondPlural,
    ThirdPlural,
}

impl Possessor {
    pub const ALL: [Self; 8] = [Self::FirstSingular, Self::SecondSingular, Self::ThirdMasculine, Self::ThirdFeminine, Self::FirstPluralExclusive, Self::FirstPluralInclusive, Self::SecondPlural, Self::ThirdPlural];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Person {
    FirstSingular,
    SecondSingular,
    ThirdMasculine,
    ThirdFeminine,
    FirstPlural,
    SecondPlural,
    ThirdPlural,
}

impl Person {
    pub const ALL: [Self; 7] = [Self::FirstSingular, Self::SecondSingular, Self::ThirdMasculine, Self::ThirdFeminine, Self::FirstPlural, Self::SecondPlural, Self::ThirdPlural];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Tense {
    Present,
    PresentProgressive,
    Past,
    PastProgressive,
}

impl Tense {
    pub const ALL: [Self; 4] = [Self::Present, Self::PresentProgressive, Self::Past, Self::PastProgressive];
}

/// Settings for systematic choices. `Somali::default()` is what the free functions use.
